.version 8.2
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 N,
    .param .u32 IC,
    .param .u32 IH,
    .param .u32 IW,
    .param .u32 OC,
    .param .u32 OH,
    .param .u32 OW,
    .param .u32 KH,
    .param .u32 KW,
    .param .u32 stride,
    .param .u32 padding,
    .param .u32 dilation,
    .param .u32 has_bias
)
