    ld.param.u32 %r1, [IC];
    ld.param.u32 %r2, [IH];
    ld.param.u32 %r3, [IW];
    ld.param.u32 %r4, [OC];
    ld.param.u32 %r5, [OH];
    ld.param.u32 %r6, [OW];
    ld.param.u32 %r7, [KH];
    ld.param.u32 %r8, [KW];
    ld.param.u32 %r9, [stride];
    ld.param.u32 %r10, [padding];
    ld.param.u32 %r11, [dilation];
    ld.param.u32 %r12, [has_bias];

    mov.u32 %r13, %tid.x;
    mov.u32 %r14, %ctaid.x;
    mov.u32 %r15, %ntid.x;
    mad.lo.u32 %r16, %r14, %r15, %r13;

    mov.u32 %r17, %tid.y;
    mov.u32 %r18, %ctaid.y;
    mov.u32 %r19, %ntid.y;
    mad.lo.u32 %r20, %r18, %r19, %r17;

    mov.u32 %r21, %ctaid.z;
    div.u32 %r22, %r21, %r4;
    rem.u32 %r23, %r21, %r4;

    setp.ge.u32 %p0, %r16, %r6;
    setp.ge.u32 %p1, %r20, %r5;
    setp.ge.u32 %p2, %r22, %r0;
    or.pred %p3, %p0, %p1;
    or.pred %p4, %p3, %p2;
