    @%p6 bra END_KH;

    mul.lo.s32 %r27, %r20, %r9;
    mul.lo.s32 %r28, %r25, %r11;
    add.s32 %r29, %r27, %r28;
    sub.s32 %r30, %r29, %r10;

    setp.lt.s32 %p7, %r30, 0;
    setp.ge.s32 %p8, %r30, %r2;
    or.pred %p9, %p7, %p8;
    @%p9 bra SKIP_KH;

    mov.u32 %r26, 0;
