    setp.ge.u32 %p10, %r26, %r8;
    @%p10 bra END_KW;

    mul.lo.s32 %r31, %r16, %r9;
    mul.lo.s32 %r32, %r26, %r11;
    add.s32 %r33, %r31, %r32;
    sub.s32 %r34, %r33, %r10;

    setp.lt.s32 %p11, %r34, 0;
    setp.ge.s32 %p12, %r34, %r3;
    or.pred %p13, %p11, %p12;
    @%p13 bra SKIP_KW;

    mad.lo.s32 %r35, %r22, %r1, %r24;
    mad.lo.s32 %r36, %r35, %r2, %r30;
    mad.lo.s32 %r37, %r36, %r3, %r34;

