    mad.lo.s32 %r39, %r38, %r7, %r25;
    mad.lo.s32 %r40, %r39, %r8, %r26;

    mul.wide.s32 %rd6, %r40, 4;
    add.s64 %rd7, %rd1, %rd6;
    ld.global.f32 %f2, [%rd7];

    fma.rn.f32 %f0, %f1, %f2, %f0;

SKIP_KW:
    add.u32 %r26, %r26, 1;
    bra LOOP_KW;
END_KW:

SKIP_KH:
    add.u32 %r25, %r25, 1;
    bra LOOP_KH;
END_KH:

