    bra LOOP_IC;
END_IC:

    setp.eq.u32 %p14, %r12, 0;
    @%p14 bra STORE;

    mul.wide.s32 %rd10, %r23, 4;
    add.s64 %rd11, %rd2, %rd10;
    ld.global.f32 %f3, [%rd11];
    add.f32 %f0, %f0, %f3;

STORE:
    mad.lo.s32 %r41, %r22, %r4, %r23;
    mad.lo.s32 %r42, %r41, %r5, %r20;
    mad.lo.s32 %r43, %r42, %r6, %r16;

    mul.wide.s32 %rd8, %r43, 4;
    add.s64 %rd9, %rd3, %rd8;
    st.global.f32 [%rd9], %f0;

